package com.whiteboard.workspace.controller;

import com.whiteboard.workspace.model.Whiteboard;
import com.whiteboard.workspace.repository.WhiteboardRepository;
import com.whiteboard.workspace.service.SvgExportService;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/workspace/canvas")
public class WhiteboardController {

    private final WhiteboardRepository whiteboardRepository;
    private final SvgExportService svgExportService;

    public WhiteboardController(WhiteboardRepository whiteboardRepository, SvgExportService svgExportService) {
        this.whiteboardRepository = whiteboardRepository;
        this.svgExportService = svgExportService;
    }

    @GetMapping(value = "/boards/{boardId}/export.svg", produces = "image/svg+xml")
    public ResponseEntity<String> exportBoardCanvasAsSvg(
            @PathVariable Long boardId,
            Authentication authentication) {
        Whiteboard board = whiteboardRepository.findById(boardId)
                .orElseThrow(() -> new IllegalArgumentException("Whiteboard canvas not found"));
        if (!board.hasMember(authentication.getName())) {
            throw new AccessDeniedException("Caller is not a member of the workspace owning this whiteboard");
        }
        String svgXml = svgExportService.renderCanvasSvg(board);
        return ResponseEntity.ok()
                .contentType(MediaType.parseMediaType("image/svg+xml"))
                .body(svgXml);
    }
}
